Use a non-transactional migration. The key points are: add nullable column, install trigger before backfill, backfill in batches, and never overwrite a newer value written by the trigger.

```sql
-- Must run outside a transaction because of CREATE INDEX CONCURRENTLY
-- e.g. Rails: disable_ddl_transaction!

SET lock_timeout = '5s';
SET statement_timeout = '0';

ALTER TABLE users
  ADD COLUMN last_login_at timestamptz;

-- Needed for efficient per-user latest-login lookup.
CREATE INDEX CONCURRENTLY IF NOT EXISTS
  index_login_events_on_user_id_occurred_at_desc
ON login_events (user_id, occurred_at DESC);

-- Keep users.last_login_at current for new login events.
CREATE OR REPLACE FUNCTION update_user_last_login_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  UPDATE users
  SET last_login_at = GREATEST(last_login_at, NEW.occurred_at)
  WHERE id = NEW.user_id;

  RETURN NEW;
END;
$$;

CREATE TRIGGER login_events_update_user_last_login_at
AFTER INSERT ON login_events
FOR EACH ROW
EXECUTE FUNCTION update_user_last_login_at();

-- Backfill in batches. CALL this outside an explicit transaction.
CREATE OR REPLACE PROCEDURE backfill_users_last_login_at(batch_size bigint DEFAULT 10000)
LANGUAGE plpgsql
AS $$
DECLARE
  min_id bigint;
  max_id bigint;
  start_id bigint;
  end_id bigint;
BEGIN
  SELECT min(id), max(id) INTO min_id, max_id FROM users;

  start_id := min_id;

  WHILE start_id IS NOT NULL AND start_id <= max_id LOOP
    end_id := start_id + batch_size - 1;

    UPDATE users u
    SET last_login_at = GREATEST(u.last_login_at, latest.last_login_at)
    FROM (
      SELECT u2.id AS user_id, le.occurred_at AS last_login_at
      FROM users u2
      JOIN LATERAL (
        SELECT occurred_at
        FROM login_events le
        WHERE le.user_id = u2.id
        ORDER BY occurred_at DESC
        LIMIT 1
      ) le ON true
      WHERE u2.id BETWEEN start_id AND end_id
    ) latest
    WHERE u.id = latest.user_id
      AND (
        u.last_login_at IS NULL
        OR latest.last_login_at > u.last_login_at
      );

    COMMIT;

    start_id := end_id + 1;
  END LOOP;
END;
$$;

CALL backfill_users_last_login_at(10000);

DROP PROCEDURE backfill_users_last_login_at(bigint);
```

Down migration:

```sql
DROP TRIGGER IF EXISTS login_events_update_user_last_login_at ON login_events;
DROP FUNCTION IF EXISTS update_user_last_login_at();

ALTER TABLE users
  DROP COLUMN IF EXISTS last_login_at;

DROP INDEX CONCURRENTLY IF EXISTS index_login_events_on_user_id_occurred_at_desc;
```
